#!/bin/bash
# ORIGINAL (LB2b): the driver that makes test/files/test_lb2b_swipl.out with swipl 10.1.19 — the rows (generated by
# gen_lb2b_rows.py), the test's own DRIVER text (cut out of test/files/test_lb2b_swipl.jl), `timeout 20` on every swipl call,
# two runs in two fresh fixture directories, byte-identical or no .out.
# Usage: bash evidence/LB2B/run_lb2b_rows.sh <scratch-dir> (run from the repository root; <scratch-dir> is new or empty)
set -eu
root=$(pwd)
scr=$1
mkdir -p "$scr"
python3 -I "$root/evidence/LB2B/gen_lb2b_rows.py" "$scr/rows.pl"
python3 -I - "$root/test/files/test_lb2b_swipl.jl" "$scr/rows.pl" "$scr/drv.pl" <<'PY'
import re, sys
jl, rows, out = sys.argv[1:4]
src = open(jl).read()
i = src.index('const DRIVER = raw"""') + len('const DRIVER = raw"""')
driver = src[i:src.index('"""', i)]
names = re.findall(r'^(t\d+)\(R\) :-', open(rows).read(), re.M)
names = list(dict.fromkeys(names))
open(out, 'w').write(driver + ":- initialization((fz_run('%s', [%s]), halt)).\n" % (rows, ",".join(names)))
PY
for k in 1 2; do
  d="$scr/run$k"
  mkdir "$d"
  (cd "$d" && bash "$root/evidence/LB2B/fixtures.sh" && timeout 20 swipl -q "$scr/drv.pl" < /dev/null > "$scr/out$k.txt" 2> "$scr/err$k.txt")
done
cmp "$scr/out1.txt" "$scr/out2.txt"
cp "$scr/rows.pl" "$root/test/files/test_lb2b_swipl.pl"
cp "$scr/out1.txt" "$root/evidence/LB2B/test_lb2b_swipl.out"
cp "$scr/out1.txt" "$root/test/files/test_lb2b_swipl.out"
wc -l "$scr/out1.txt"
